/**
 * Smart Wolffia Cultivation System V3.0.1
 * Supabase Database Configuration & ESP32 Telemetry Schema
 */

// Supabase Configuration
// Can also be configured directly via the Settings view in dashboard.html
const WOLFFIA_SUPABASE_CONFIG = {
  url: localStorage.getItem('wolffia_supabase_url') || '',
  anonKey: localStorage.getItem('wolffia_supabase_key') || '',
  table: 'wolffia_telemetry'
};

/**
 * SQL Schema for Supabase / PostgreSQL table creation:
 * 
 * CREATE TABLE IF NOT EXISTS public.wolffia_telemetry (
 *   id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 *   created_at TIMESTAMPTZ DEFAULT timezone('utc'::text, now()) NOT NULL,
 *   device_id TEXT DEFAULT 'ESP32-WOLFFIA-01' NOT NULL,
 *   temperature NUMERIC(4, 2) NOT NULL,
 *   ph NUMERIC(3, 2) NOT NULL,
 *   water_level NUMERIC(4, 1) NOT NULL,
 *   light NUMERIC(4, 1) NOT NULL,
 *   rssi INTEGER DEFAULT -58,
 *   device_status TEXT DEFAULT 'Online'
 * );
 * 
 * -- Enable Realtime
 * ALTER PUBLICATION supabase_realtime ADD TABLE public.wolffia_telemetry;
 * 
 * -- Enable Public Access Policies (RLS)
 * ALTER TABLE public.wolffia_telemetry ENABLE ROW LEVEL SECURITY;
 * CREATE POLICY "Allow public read" ON public.wolffia_telemetry FOR SELECT USING (true);
 * CREATE POLICY "Allow public insert" ON public.wolffia_telemetry FOR INSERT WITH CHECK (true);
 */

let supabaseClient = null;

function initWolffiaSupabase() {
  if (typeof supabase !== 'undefined' && WOLFFIA_SUPABASE_CONFIG.url && WOLFFIA_SUPABASE_CONFIG.anonKey) {
    try {
      supabaseClient = supabase.createClient(WOLFFIA_SUPABASE_CONFIG.url, WOLFFIA_SUPABASE_CONFIG.anonKey);
      window.supabaseClient = supabaseClient;
      console.log('Supabase client initialized for Smart Wolffia IoT telemetry');
      return supabaseClient;
    } catch (e) {
      console.warn('Failed to initialize Supabase client:', e);
    }
  }
  return null;
}

// Auto-run initialization
initWolffiaSupabase();

